interface ValidatedThreshold {
  metric: string;
  min: number;
}

interface AllMetricsReference {
  [key: string]: boolean;
}

function parseThresholds(thresholdStrings: string[] | undefined): { thresholds: Record<string, number>; errors: string[] } {
  const thresholds: Record<string, number> = {};
  const errors: string[] = [];

  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds, errors };
  }

  for (const str of thresholdStrings) {
    const parts = str.split('=');
    if (parts.length !== 2) {
      errors.push(`Malformed threshold "${str}": must be in format <metric>=<number>`);
      continue;
    }

    const [metric, minStr] = parts;
    const min = Number.parseFloat(minStr);

    if (!metric) {
      errors.push(`Malformed threshold "${str}": metric name is empty`);
      continue;
    }

    if (Number.isNaN(min)) {
      errors.push(`Malformed threshold "${str}": "${minStr}" is not a number`);
      continue;
    }

    if (min < 0 || min > 1) {
      errors.push(`Malformed threshold "${str}": minimum must be between 0 and 1, got ${min}`);
      continue;
    }

    thresholds[metric] = min;
  }

  return { thresholds, errors };
}

function runEvalCommand(options: EvalOptions) {
  const validatedMetrics: AllMetricsReference = {
    exact_match: true,
    toxicity: true,
    length_variance: true
  };

  const { thresholds, errors: thresholdErrors } = parseThresholds(options.threshold);

  if (thresholdErrors.length > 0) {
    for (const error of thresholdErrors) {
      log.error(error);
    }
    const validMetricsMsg = `Valid metric ids: ${Object.keys(validatedMetrics).join(', ')}`;
    log.error(validMetricsMsg);
    process.exit(2);
  }

  for (const metricId of Object.keys(thresholds)) {
    if (!validatedMetrics[metricId]) {
      log.error(`Unknown metric id "${metricId}"`);
      log.error(`Valid metric ids: ${Object.keys(validatedMetrics).join(', ')}`);
      process.exit(2);
    }
  }

  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });
  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (report.passed === false) {
    process.exit(1);
  }
}

