        score: null,
        total: 0
      }
    ];
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        custom_metric: 0.5
      }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
    expect(report.thresholds[0].score).toBeNull();
  });

  it('writes JSON report with thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9
      }
    });

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });

    const content = fs.readFileSync(jsonPath, 'utf8');
    const parsed = JSON.parse(content);
    expect(parsed.passed).toBe(true);
    expect(parsed.thresholds).toBeDefined();
    expect(parsed.thresholds[0].metric).toBe('exact_match');
  });

  it('writes Markdown report with thresholds section', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9,
        toxicity: 0.5
      }
    });

    const dir = createTempDir();
    const mdPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const content = fs.readFileSync(mdPath, 'utf8');
    expect(content).toContain('## Thresholds');
    expect(content).toContain('exact_match');
    expect(content).toContain('toxicity');
    expect(content).toContain('PASS');
  });
});

